SELECT DISTINCT b.id, b.title, b.summary, b.cover_img, b.author_id, b.category_id, b.status, b.visibility, b.is_top, b.view_count, (SELECT COUNT(*) FROM tb_user_like ul WHERE ul.target_type = 'blog' AND ul.target_id = b.id AND ul.status = 1 AND ul.deleted = 0) AS like_count, (SELECT COUNT(*) FROM tb_comment c WHERE c.blog_id = b.id AND c.status = 1 AND c.deleted = 0) AS comment_count, b.publish_time, b.create_time, b.update_time, b.status_changed_time, u.nickname as author_name, u.avatar as author_avatar, c.name as category_name, t.id as tag_id, t.name as tag_name, t.color as tag_color FROM tb_blog b LEFT JOIN tb_user u ON b.author_id = u.id LEFT JOIN tb_category c ON b.category_id = c.id LEFT JOIN tb_blog_tag bt ON b.id = bt.blog_id LEFT JOIN tb_tag t ON bt.tag_id = t.id AND t.deleted = 0 WHERE b.deleted = 0
AND b.category_id = #{categoryId}
AND b.id IN (SELECT blog_id FROM tb_blog_tag WHERE tag_id = #{tagId})
AND (b.title LIKE CONCAT('%', #{keyword}, '%') OR b.summary LIKE CONCAT('%', #{keyword}, '%'))
AND b.status = #{status}
ORDER BY b.is_top DESC, b.create_time DESC

SELECT DISTINCT b.id, b.title, b.summary, b.content, b.cover_img, b.author_id, b.category_id, b.status, b.visibility, b.is_top, b.view_count, (SELECT COUNT(*) FROM tb_user_like ul WHERE ul.target_type = 'blog' AND ul.target_id = b.id AND ul.status = 1 AND ul.deleted = 0) AS like_count, (SELECT COUNT(*) FROM tb_comment c WHERE c.blog_id = b.id AND c.status = 1 AND c.deleted = 0) AS comment_count, b.publish_time, b.status_changed_time, b.create_time, b.update_time, u.nickname as author_name, u.avatar as author_avatar, c.name as category_name FROM tb_blog b LEFT JOIN tb_user u ON b.author_id = u.id LEFT JOIN tb_category c ON b.category_id = c.id LEFT JOIN tb_blog_tag bt ON b.id = bt.blog_id WHERE b.deleted = 0 AND b.status = 1 AND b.id != #{blogId} AND ( b.category_id = #{categoryId}
OR bt.tag_id IN
#{tagId}
) ORDER BY CASE WHEN b.category_id = #{categoryId} THEN 1 ELSE 2 END, b.view_count DESC, b.publish_time DESC LIMIT #{limit}

SELECT b.id, b.title, b.summary, b.content, b.cover_img, b.author_id, b.category_id, b.status, b.visibility, b.is_top, b.view_count, (SELECT COUNT(*) FROM tb_user_like ul WHERE ul.target_type = 'blog' AND ul.target_id = b.id AND ul.status = 1 AND ul.deleted = 0) AS like_count, (SELECT COUNT(*) FROM tb_comment c WHERE c.blog_id = b.id AND c.status = 1 AND c.deleted = 0) AS comment_count, b.publish_time, b.status_changed_time, b.create_time, b.update_time, u.nickname as author_name, u.avatar as author_avatar, c.name as category_name FROM tb_blog b LEFT JOIN tb_user u ON b.author_id = u.id LEFT JOIN tb_category c ON b.category_id = c.id WHERE b.deleted = 0 AND b.status = 1
AND b.category_id = #{categoryId}
AND b.id < #{blogId} ORDER BY b.id DESC LIMIT 1

SELECT b.id, b.title, b.summary, b.content, b.cover_img, b.author_id, b.category_id, b.status, b.visibility, b.is_top, b.view_count, (SELECT COUNT(*) FROM tb_user_like ul WHERE ul.target_type = 'blog' AND ul.target_id = b.id AND ul.status = 1 AND ul.deleted = 0) AS like_count, (SELECT COUNT(*) FROM tb_comment c WHERE c.blog_id = b.id AND c.status = 1 AND c.deleted = 0) AS comment_count, b.publish_time, b.status_changed_time, b.create_time, b.update_time, u.nickname as author_name, u.avatar as author_avatar, c.name as category_name FROM tb_blog b LEFT JOIN tb_user u ON b.author_id = u.id LEFT JOIN tb_category c ON b.category_id = c.id WHERE b.deleted = 0 AND b.status = 1
AND b.category_id = #{categoryId}
AND b.id > #{blogId} ORDER BY b.id ASC LIMIT 1

SELECT DISTINCT b.id, b.title, b.summary, b.content, b.cover_img, b.author_id, b.category_id, b.status, b.visibility, b.is_top, b.view_count, (SELECT COUNT(*) FROM tb_user_like ul WHERE ul.target_type = 'blog' AND ul.target_id = b.id AND ul.status = 1 AND ul.deleted = 0) AS like_count, (SELECT COUNT(*) FROM tb_comment c WHERE c.blog_id = b.id AND c.status = 1 AND c.deleted = 0) AS comment_count, b.publish_time, b.status_changed_time, b.create_time, b.update_time, u.nickname as author_name, u.avatar as author_avatar, c.name as category_name FROM tb_blog b LEFT JOIN tb_user u ON b.author_id = u.id LEFT JOIN tb_category c ON b.category_id = c.id INNER JOIN tb_blog_tag bt ON b.id = bt.blog_id WHERE b.deleted = 0 AND b.status = 1
AND b.id != #{excludeBlogId}
AND bt.tag_id IN
#{tagId}
ORDER BY b.publish_time DESC LIMIT #{limit}

SELECT b.id, b.title, b.summary, b.content, b.cover_img, b.author_id, b.category_id, b.status, b.visibility, b.is_top, b.view_count, (SELECT COUNT(*) FROM tb_user_like ul WHERE ul.target_type = 'blog' AND ul.target_id = b.id AND ul.status = 1 AND ul.deleted = 0) AS like_count, (SELECT COUNT(*) FROM tb_comment c WHERE c.blog_id = b.id AND c.status = 1 AND c.deleted = 0) AS comment_count, b.publish_time, b.status_changed_time, b.create_time, b.update_time, u.nickname as author_name, u.avatar as author_avatar, c.name as category_name FROM tb_blog b LEFT JOIN tb_user u ON b.author_id = u.id LEFT JOIN tb_category c ON b.category_id = c.id WHERE b.deleted = 0 AND b.author_id = #{authorId}
AND b.status = #{status}
ORDER BY b.update_time DESC, b.create_time DESC

SELECT DISTINCT b.id, b.title, b.summary, b.cover_img, b.author_id, b.category_id, b.status, b.visibility, b.is_top, b.view_count, (SELECT COUNT(*) FROM tb_user_like ul WHERE ul.target_type = 'blog' AND ul.target_id = b.id AND ul.status = 1 AND ul.deleted = 0) AS like_count, (SELECT COUNT(*) FROM tb_comment c WHERE c.blog_id = b.id AND c.status = 1 AND c.deleted = 0) AS comment_count, b.publish_time, b.create_time, b.update_time, b.status_changed_time, u.nickname as author_name, u.avatar as author_avatar, c.name as category_name, t.id as tag_id, t.name as tag_name, t.color as tag_color FROM tb_blog b LEFT JOIN tb_user u ON b.author_id = u.id LEFT JOIN tb_category c ON b.category_id = c.id LEFT JOIN tb_blog_tag bt ON b.id = bt.blog_id LEFT JOIN tb_tag t ON bt.tag_id = t.id AND t.deleted = 0 WHERE b.deleted = 0 AND b.status = 1 AND b.id != #{blogId} AND ( b.category_id = #{categoryId}
OR bt.tag_id IN
#{tagId}
) ORDER BY CASE WHEN b.category_id = #{categoryId} THEN 1 ELSE 2 END, b.view_count DESC, b.publish_time DESC LIMIT #{limit}

SELECT candidate.id FROM ( SELECT b.id, CASE WHEN #{categoryId} IS NOT NULL AND b.category_id = #{categoryId} THEN 1 ELSE 0 END AS same_category,
COUNT(DISTINCT CASE WHEN bt.tag_id IN
#{tagId}
THEN bt.tag_id END) AS tag_overlap_count,
0 AS tag_overlap_count,
b.publish_time, b.view_count FROM tb_blog b LEFT JOIN tb_blog_tag bt ON b.id = bt.blog_id WHERE b.deleted = 0 AND b.status = 1 AND b.id != #{blogId} AND (
b.category_id = #{categoryId} OR
bt.tag_id IN
#{tagId}
OR
) GROUP BY b.id, b.category_id, b.publish_time, b.view_count ) candidate ORDER BY candidate.same_category DESC, candidate.tag_overlap_count DESC, candidate.publish_time DESC, candidate.view_count DESC LIMIT #{limit}

SELECT b.id, b.title, b.summary, b.cover_img, b.author_id, b.category_id, b.status, b.visibility, b.is_top, b.view_count, (SELECT COUNT(*) FROM tb_user_like ul WHERE ul.target_type = 'blog' AND ul.target_id = b.id AND ul.status = 1 AND ul.deleted = 0) AS like_count, (SELECT COUNT(*) FROM tb_comment c WHERE c.blog_id = b.id AND c.status = 1 AND c.deleted = 0) AS comment_count, b.publish_time, b.create_time, b.update_time, b.status_changed_time, u.nickname as author_name, u.avatar as author_avatar, c.name as category_name, t.id as tag_id, t.name as tag_name, t.color as tag_color FROM tb_blog b LEFT JOIN tb_user u ON b.author_id = u.id LEFT JOIN tb_category c ON b.category_id = c.id LEFT JOIN tb_blog_tag bt ON b.id = bt.blog_id LEFT JOIN tb_tag t ON bt.tag_id = t.id AND t.deleted = 0 WHERE b.deleted = 0 AND b.status = 1 AND b.id IN
#{id}
ORDER BY FIELD(b.id,
#{id}
)
